namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string Department { get; set; }
    public required Instructor Instructor { get; set; }
    public bool IsFeatured { get; set; }
}

public class Instructor
{
    public required string Name { get; set; }
    public required string Title { get; set; }
    public required string Bio { get; set; }
    public required string Email { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<string> GetDepartments();
    IReadOnlyList<Course> GetCourses(string? department = null, string? search = null);
    Course? GetCourse(int id);
    IReadOnlyList<Course> GetFeaturedCourses();
    bool SubmitEnrollment(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, Code = "CS 101", Title = "Introduction to Computer Science",
            Description = "A broad introduction to computer science covering computational thinking, basic algorithms, data representation, and an overview of major areas in the field. No prior programming experience required.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Department = "Computer Science", IsFeatured = true,
            Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Professor", Bio = "Dr. Lovelace has over 15 years of experience teaching introductory CS courses and researches CS education methods.", Email = "alovelace@university.edu" }
        },
        new()
        {
            Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes complexity analysis.",
            Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Department = "Computer Science", IsFeatured = true,
            Instructor = new() { Name = "Dr. Alan Turing", Title = "Associate Professor", Bio = "Dr. Turing specializes in algorithm design and computational complexity. He has published extensively on graph algorithms.", Email = "aturing@university.edu" }
        },
        new()
        {
            Id = 3, Code = "MATH 201", Title = "Linear Algebra",
            Description = "Systems of linear equations, matrices, determinants, vector spaces, eigenvalues and eigenvectors. Applications to geometry, differential equations, and data science.",
            Credits = 3, Schedule = "Mon/Wed 1:00–2:15 PM", Department = "Mathematics",
            Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Dr. Noether is an award-winning mathematician whose research focuses on abstract algebra and theoretical physics applications.", Email = "enoether@university.edu" }
        },
        new()
        {
            Id = 4, Code = "MATH 101", Title = "Calculus I",
            Description = "Limits, continuity, differentiation, and integration of single-variable functions. Applications including rates of change, optimization, and area under curves.",
            Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Department = "Mathematics", IsFeatured = true,
            Instructor = new() { Name = "Dr. Srinivasa Ramanujan", Title = "Professor", Bio = "Dr. Ramanujan brings an intuitive, example-driven approach to calculus instruction, drawing on research in number theory.", Email = "sramanujan@university.edu" }
        },
        new()
        {
            Id = 5, Code = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy, momentum, rotational motion, and introductory thermodynamics with laboratory work.",
            Credits = 4, Schedule = "Tue/Thu 9:00–10:30 AM, Lab Fri 2:00–4:50 PM", Department = "Physics",
            Instructor = new() { Name = "Dr. Marie Curie", Title = "Professor", Bio = "Dr. Curie is a renowned physicist with a focus on experimental methods and science communication.", Email = "mcurie@university.edu" }
        },
        new()
        {
            Id = 6, Code = "ENG 201", Title = "Creative Writing",
            Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction. Students produce a portfolio of original work and participate in peer review sessions.",
            Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", Department = "English",
            Instructor = new() { Name = "Prof. Virginia Woolf", Title = "Professor", Bio = "Prof. Woolf is a published novelist and essayist who has taught creative writing for over a decade.", Email = "vwoolf@university.edu" }
        },
        new()
        {
            Id = 7, Code = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from prehistory through the late medieval period, covering political, social, economic, and cultural developments across Africa, Asia, Europe, and the Americas.",
            Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Department = "History",
            Instructor = new() { Name = "Dr. Howard Zinn", Title = "Associate Professor", Bio = "Dr. Zinn specializes in social history and brings a people-centered perspective to the study of world civilizations.", Email = "hzinn@university.edu" }
        },
        new()
        {
            Id = 8, Code = "CS 401", Title = "Machine Learning",
            Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, decision trees, and model evaluation. Hands-on projects using Python.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Department = "Computer Science", IsFeatured = true,
            Instructor = new() { Name = "Dr. Geoffrey Hinton", Title = "Professor", Bio = "Dr. Hinton is a pioneer in deep learning research and has mentored dozens of graduate students in AI.", Email = "ghinton@university.edu" }
        },
        new()
        {
            Id = 9, Code = "BIO 101", Title = "Introduction to Biology",
            Description = "Fundamental concepts of biology including cell structure, genetics, evolution, ecology, and physiology. Includes weekly laboratory sessions.",
            Credits = 4, Schedule = "Mon/Wed 9:00–10:15 AM, Lab Thu 1:00–3:50 PM", Department = "Biology",
            Instructor = new() { Name = "Dr. Charles Darwin", Title = "Professor", Bio = "Dr. Darwin is an evolutionary biologist with a passion for making biology accessible and engaging for all students.", Email = "cdarwin@university.edu" }
        },
        new()
        {
            Id = 10, Code = "CHEM 101", Title = "General Chemistry I",
            Description = "Atomic structure, chemical bonding, stoichiometry, states of matter, and thermochemistry. Laboratory work emphasizes quantitative techniques and scientific reporting.",
            Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM, Lab Wed 2:00–4:50 PM", Department = "Chemistry",
            Instructor = new() { Name = "Dr. Linus Pauling", Title = "Professor", Bio = "Dr. Pauling is a celebrated chemist known for groundbreaking work in molecular biology and chemical bonding.", Email = "lpauling@university.edu" }
        }
    ];

    public IReadOnlyList<string> GetDepartments()
    {
        return Courses.Select(c => c.Department).Distinct().Order().ToList();
    }

    public IReadOnlyList<Course> GetCourses(string? department = null, string? search = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(department))
            query = query.Where(c => c.Department.Equals(department, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.OrderBy(c => c.Department).ThenBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id)
    {
        return Courses.FirstOrDefault(c => c.Id == id);
    }

    public IReadOnlyList<Course> GetFeaturedCourses()
    {
        return Courses.Where(c => c.IsFeatured).ToList();
    }

    public bool SubmitEnrollment(EnrollmentRequest request)
    {
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && Courses.Any(c => c.Id == request.CourseId);
    }
}

