@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">University Course Catalog</h1>
    <p class="lead text-muted">Browse departments, explore courses, and enroll for the upcoming semester.</p>
    <a href="/courses" class="btn btn-primary btn-lg mt-2">Browse All Courses</a>
</div>

<h2 class="mb-3">Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4 mb-5">
    @foreach (var course in featuredCourses)
    {
        <div class="col">
            <FeaturedCourseCard Course="course" />
        </div>
    }
</div>

<h2 class="mb-3">Departments</h2>
<div class="list-group mb-4" style="max-width: 500px;">
    @foreach (var dept in departments)
    {
        <DepartmentLinkCard Department="@dept" Count="@courseCounts[dept]" />
    }
</div>

@code {
    private IReadOnlyList<Models.Course> featuredCourses = [];
    private IReadOnlyList<string> departments = [];
    private Dictionary<string, int> courseCounts = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
        var allCourses = Catalog.GetCourses();
        courseCounts = departments.ToDictionary(
            d => d,
            d => allCourses.Count(c => c.Department == d));
    }
}

