@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICatalogService Catalog

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CourseFilters Search="@Search" Department="@Department" Departments="departments" />

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted mb-3">Showing @courses.Count course(s)</p>
    @foreach (var course in courses)
    {
        <CourseListItem Course="course" />
    }
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public string? Department { get; set; }

    private IReadOnlyList<Models.Course> courses = [];
    private IReadOnlyList<string> departments = [];

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.GetCourses(Department, Search);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <div class="alert alert-warning">Course not found.</div>
}
else
{
    <PageTitle>@course.Code — University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="/courses?department=@Uri.EscapeDataString(course.Department)">@course.Department</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code — @course.Title</h1>
    <div class="row mt-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4 class="mt-4">Details</h4>
            <table class="table table-bordered" style="max-width: 400px;">
                <tr><th>Credits</th><td>@course.Credits</td></tr>
                <tr><th>Schedule</th><td>@course.Schedule</td></tr>
                <tr><th>Department</th><td>@course.Department</td></tr>
            </table>

            <a href="/enroll?courseId=@course.Id" class="btn btn-success mt-2">Enroll in This Course</a>
        </div>
        <div class="col-md-4">
            <InstructorBio Instructor="course.Instructor" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Models.Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>Enroll — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
           <strong>@selectedCourseTitle</strong> has been received.</p>
        <a href="/courses" class="btn btn-outline-primary mt-2">Back to Courses</a>
    </div>
}
else
{
    if (validationError is not null)
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <form method="post" style="max-width: 500px;">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" id="studentName" name="Model.StudentName" value="@Model.StudentName"
                   class="form-control" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId"
                   class="form-control" required placeholder="e.g. S12345678" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="Model.CourseId" class="form-select" required>
                <option value="">— Select a course —</option>
                @foreach (var c in courses)
                {
                    <option value="@c.Id" selected="@(c.Id == Model.CourseId)">@c.Code — @c.Title</option>
                }
